// Get all incoming items
const allItems = $input.all();

return allItems.map(item => {
    // Get the Google Sheet URL from the webhook body
    const sheetUrl = item.json.body.sheet_url;

    // Extract Spreadsheet ID
    const match = sheetUrl.match(/\/spreadsheets\/d\/([a-zA-Z0-9-_]+)/);

    return {
        json: {
            document: match ? match[1] : ""
        }
    };
});

const allItems = $input.all();

const processedData = allItems.map(item => {
    const row = item.json;

    return {
        timestamp: row.timestamp,
        machine_id: row.machine_id,
        production_line: row.production_line,
        status: row.status,
        cycle_time_sec: Number(row.cycle_time_sec || 0),
        units_produced: Number(row.units_produced || 0),
        defects: Number(row.defects || 0),
        downtime_min: Number(row.downtime_min || 0),
        shift: row.shift
    };
});

return [
    {
        json: {
            data: processedData
        }
    }
];

const allItems = $input.all();

return allItems.map(item => {
    try {
        const parsed = JSON.parse(item.json.response);

        return {
            json: parsed
        };
    } catch (err) {
        return {
            json: {
                error: "Invalid JSON returned by Gemini",
                raw: item.json.response
            }
        };
    }
});
